  @protected
  void sse_encode_metadata_event(MetadataEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MetadataEvent_Failed(error: final error):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_otter_error(error, serializer);
      case MetadataEvent_ReadingPdf():
        sse_encode_i_32(1, serializer);
      case MetadataEvent_ResolvingIdentifier():
        sse_encode_i_32(2, serializer);
      case MetadataEvent_SearchingTitle():
        sse_encode_i_32(3, serializer);
      case MetadataEvent_Completed(report: final report):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_metadata_repair(report, serializer);
    }
  }

